/* =====================================================================
   V7_1 — DỮ LIỆU MẪU phân hệ Quản lý kho (chỉ môi trường dev, [FAKE-DATA])
   Sinh tự động bằng backend/database/kho-seed/gen-v7_1.mjs (nhà hàng Royal Beef):
   106 nguyên liệu (NL001–NL006 đã có từ V1_1), 6 nhà cung cấp, 106 liên kết giá theo đơn vị mua,
   lịch sử đổi giá, công thức định lượng đủ 56 món (giả — Bếp sửa ở trang Công thức), tồn đầu kỳ và vài lần xuất bếp
   để có đủ trạng thái Đủ hàng / Sắp hết / Hết hàng. Ngày tháng tính lùi từ ngày chạy migration.
   ===================================================================== */

SET @thao = (SELECT id FROM users WHERE username = 'thao.bui');
SET @tuan = (SELECT id FROM users WHERE username = 'tuan.nguyen');

/* ---------------------------------------------------------------- Nguyên liệu */
UPDATE ingredients SET group_key = 'meat', note = 'Bảo quản ngăn mát 0–4°C, dùng trong 5 ngày.', created_by = @thao, created_at = TIMESTAMP(CURDATE() - INTERVAL 35 DAY, '08:00:00') WHERE code = 'NL001';
UPDATE ingredients SET group_key = 'meat', note = NULL, created_by = @thao, created_at = TIMESTAMP(CURDATE() - INTERVAL 35 DAY, '08:00:00') WHERE code = 'NL002';
UPDATE ingredients SET group_key = 'meat', note = NULL, created_by = @thao, created_at = TIMESTAMP(CURDATE() - INTERVAL 35 DAY, '08:00:00') WHERE code = 'NL003';
UPDATE ingredients SET group_key = 'meat', note = NULL, created_by = @thao, created_at = TIMESTAMP(CURDATE() - INTERVAL 35 DAY, '08:00:00') WHERE code = 'NL004';
UPDATE ingredients SET group_key = 'other', note = 'Giao mỗi sáng, dùng trong ngày.', created_by = @thao, created_at = TIMESTAMP(CURDATE() - INTERVAL 35 DAY, '08:00:00') WHERE code = 'NL005';
UPDATE ingredients SET group_key = 'dry', note = NULL, created_by = @thao, created_at = TIMESTAMP(CURDATE() - INTERVAL 35 DAY, '08:00:00') WHERE code = 'NL006';
UPDATE doc_sequences SET last_no = GREATEST(last_no, 106) WHERE seq_key = 'NL';

/* ---------------------------------------------------------------- Nhà cung cấp */
UPDATE suppliers SET phone = '0912000111', payment_method = 'transfer', contact_name = 'Anh Trần Văn Lộc', email = 'sales@ucchaubeef.vn', website = 'https://ucchaubeef.vn', tax_code = '1701234567', address = 'KCN Tân Tạo, Bình Tân, TP.HCM', note = 'Giao hàng lạnh trước 8 giờ sáng. Công nợ 15 ngày.', created_at = TIMESTAMP(CURDATE() - INTERVAL 35 DAY, '08:00:00') WHERE code = 'NCC001';
UPDATE supplier_status_events e JOIN suppliers s ON s.id = e.supplier_id SET e.created_at = TIMESTAMP(CURDATE() - INTERVAL 35 DAY, '08:00:00'), e.created_by = @thao WHERE s.code = 'NCC001';
UPDATE suppliers SET phone = '0912000222', payment_method = 'transfer', contact_name = 'Chị Lê Ngọc Mai', email = 'kinhdoanh@daiphatfood.vn', website = 'https://daiphatfood.vn', tax_code = '0312345678', address = 'KCN Tân Bình, TP.HCM', note = 'Công nợ 15 ngày.', created_at = TIMESTAMP(CURDATE() - INTERVAL 35 DAY, '08:00:00') WHERE code = 'NCC002';
UPDATE supplier_status_events e JOIN suppliers s ON s.id = e.supplier_id SET e.created_at = TIMESTAMP(CURDATE() - INTERVAL 35 DAY, '08:00:00'), e.created_by = @thao WHERE s.code = 'NCC002';
UPDATE suppliers SET is_active = 0, stop_reason = 'price', stop_note = 'Giá T-bone tăng 20% so với nhà cung cấp khác.' WHERE code = 'NCC006';
UPDATE doc_sequences SET last_no = GREATEST(last_no, 6) WHERE seq_key = 'NCC';

