INSERT INTO notifications (type_code, title, content, ref_table, ref_id, created_at) VALUES ('inventory', 'T-bone bò Úc đã hết hàng', 'Tồn kho về 0 kg (tối thiểu 3 kg). Nhà cung cấp Phương Nam đã ngừng hoạt động, cần chọn nhà cung cấp khác.', 'ingredients', (SELECT id FROM ingredients WHERE code = 'NL010'), NOW() - INTERVAL 26 MINUTE);
INSERT INTO notification_recipients (notification_id, user_id, is_read, read_at) SELECT @ntf, u.id, IF(r.code IN (''), 1, 0), IF(r.code IN (''), NOW(), NULL) FROM users u JOIN roles r ON r.id = u.role_id WHERE r.code IN ('warehouse','manager') AND u.deleted_at IS NULL AND u.status = 'active';
